"""Characterize native buffered base+shared penalty and threshold clipping."""
from pathlib import Path
import hashlib,json,re,subprocess
import numpy as np
R=Path(__file__).resolve().parents[1];B=R/'artifacts/analog_asic'
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def main():
 c='gf180_shared_adaptive_threshold_v1';d=B/'layout'/c;qp=d/'qualification.json';fp=d/'flat_cap_full_qualification.json';q=json.loads(qp.read_text());f=json.loads(fp.read_text());assert q['magic_drc_count']==q['gds_roundtrip_drc_count']==0 and q['lvs_unique'] and f['flat_lvs_unique'] and f['all_flat_extraction_node_ground_caps_verified'];src=d/(f['flat_subcircuit']+'_fullcap.spice');assert sha(src)==f['sha256'][src.relative_to(R).as_posix()];files={Path(__file__),qp,fp,src};text=src.read_text();ports=re.search(r'(?m)^\.subckt\s+'+f['flat_subcircuit']+r'\s+([^\n]+)',text.replace('\n+',' '))[1].split();assert ports==q['ports']
 load='gf180_mim_5x5_ports_routed';ld=B/'layout'/load;lq=ld/'qualification.json';ln=ld/(load+'.spice');files.update([lq,ln]);assert json.loads(lq.read_text())['lvs_unique'];models=B/'pdk/gf180_primitive_source/models/ngspice';files.update(models.rglob('*.spice'));pre='/workspace/'+models.relative_to(R).as_posix();stem=c+'_fullcap_native_add_clip_src'+sha(Path(__file__))[:12];rp=B/'results'/(stem+'.json');assert not rp.exists();dp=rp.with_suffix('.dat')
 lines=['Native shared adaptive threshold with buffered base and total penalty',f'.include {pre}/design.spice',f'.lib {pre}/sm141064.spice typical',f'.lib {pre}/sm141064.spice mimcap_typical',f'.lib {pre}/sm141064.spice res_typical','.param sw_stat_global=0 sw_stat_mismatch=0','.temp 27','.options method=gear reltol=1e-6 abstol=1e-16 vntol=1e-10 gmin=1e-18',text,ln.read_text(),'.global VSUBS','Vsub VSUBS 0 0','Vdd VDD 0 3.3','Vss VSS 0 0','Vcom VCOM 0 1.65','Vmin VMIN 0 1.55','Vmax VMAX 0 1.95','Ib BIAS 0 4u','Vbase BASE_SOURCE 0 PWL(0 1.5 9u 1.5 10u 1.75 19u 1.75 20u 1.85 35u 1.85)','Vpen TOTAL_SOURCE 0 PWL(0 1.65 9u 1.65 10u 1.7 19u 1.7 20u 1.85 35u 1.85)','Rb BASE_SOURCE BASE 100','Rp TOTAL_SOURCE TOTAL_PENALTY 100','Xthreshold '+' '.join(ports)+' '+f['flat_subcircuit'],f'Xload EFFECTIVE_THRESHOLD VCOM VSS {load}','.control','set numdgt=15','set wr_singlescale','set wr_vecnames','tran .005u 35u 0 .05u','wrdata /workspace/'+dp.relative_to(R).as_posix()+' v(BASE) v(TOTAL_PENALTY) v(UNCLIPPED) v(EFFECTIVE_THRESHOLD) v(BIAS) i(Vdd)','quit','.endc','.end']
 deck=B/'benches'/(stem+'.spice');deck.write_text('\n'.join(lines)+'\n');snap=B/'tools/source_snapshots'/(stem+'.py');snap.write_bytes(Path(__file__).read_bytes());files.update([deck,snap]);p=subprocess.run(['docker','run','--rm','--network','none','--memory','2g','--cpus','2','--volume',f'{R}:/workspace','--entrypoint','timeout','eventspikeseg:analog-ngspice47','120','ngspice','-b','/workspace/'+deck.relative_to(R).as_posix()],capture_output=True,text=True,timeout=135);log=p.stdout+p.stderr;lp=rp.with_suffix('.log');lp.write_text(log);files.add(lp)
 out=dict(module_simulation_completed=False,simulator_returncode=p.returncode,native_adaptive_threshold_chain_observed=False,original_float_accuracy_accepted=False,full_5ms_population_service_accepted=False,full_chip_layout_complete=False,scope='Native51MOS4R12MIM buffered BASE+TOTAL_PENALTY-VCOM addition followed by actual27MOS range clamp. Complete208branch flat substrate/coupling C with per-node verification; unchanged native devices,source/flat/GDS native Netgen LVS and full DRC0,real LEF. Separate native5x5MIM50fF output load. Three35us sequential nominal typical27C fixtures with1us input transitions and100ohm external source output resistance. VCOM1.65 and bounds1.55/1.95 are illustrative voltage fixtures,not trained unit mapping. Four native reference branches share4uA external master. TOTAL_PENALTY supplied as externally held summed penalty; channel sum/resident adaptation/RMS,decision/reset consumer connections and autonomous scheduler remain unfinished. Report actual addition/clipping error; local30mV bringup gate is not original-model precision. No full population5ms,dense array orfullchip acceptance.')
 try:
  w=np.loadtxt(dp,skiprows=1);files.add(dp);ok=bool(p.returncode==0 and w.shape[1]==7 and np.isfinite(w).all() and abs(w[-1,0]-35e-6)<1e-15 and 'aborted' not in log.lower());out['module_simulation_completed']=ok
  if ok:
   at=lambda j,u:float(np.interp(u*1e-6,w[:,0],w[:,j]));rows=[]
   for tag,u in [('lower_clip',8.5),('linear',18.5),('upper_clip',34.5)]:
    base=at(1,u);total=at(2,u);target=base+total-1.65;bounded=max(1.55,min(target,1.95));rows.append(dict(case=tag,base_v=base,total_penalty_v=total,target_unclipped_v=target,unclipped_v=at(3,u),addition_error_v=at(3,u)-target,target_effective_v=bounded,effective_v=at(4,u),effective_error_v=at(4,u)-bounded))
   out['cases']=rows;out['max_addition_error_v']=max(abs(x['addition_error_v']) for x in rows);out['max_clipped_threshold_error_v']=max(abs(x['effective_error_v']) for x in rows);out['native_adaptive_threshold_chain_observed']=bool(out['max_clipped_threshold_error_v']<.03 and rows[0]['effective_v']<rows[1]['effective_v']<rows[2]['effective_v']);out['VDD_supply_energy_j_excludes_external_analog_sources']=float(np.trapezoid(-3.3*w[:,-1],w[:,0]))
 except Exception as e:out['postprocess_error']=str(e)
 out['sha256']={p.relative_to(R).as_posix():sha(p) for p in files};rp.write_text(json.dumps(out,indent=2)+'\n');print(json.dumps({k:v for k,v in out.items() if k!='sha256'},indent=2));assert out['module_simulation_completed']
if __name__=='__main__':main()
